# MEDfl client setup for the site "{{.SiteID}}", generated by MEDomics on {{.GeneratedAt}}.
#
# Run it once on the client PC, in PowerShell opened as administrator:
#   powershell -ExecutionPolicy Bypass -File {{.FileName}}
#
# It joins the study Tailscale network, installs the MEDfl agent in C:\medfl and starts it now and at every login.
# It contains the join key and the study token of this site: do not share it with other sites.
$ErrorActionPreference = "Stop"
$ProgressPreference = "SilentlyContinue"

$SiteId = "{{.SiteID}}"
$Coordinator = "{{.CoordinatorIP}}"
$Port = "{{.Port}}"
$AuthKey = "{{.AuthKey}}"
$Token = "{{.Token}}"
$Base = "C:\medfl"

function Info($Message) { Write-Host "[MEDfl] $Message" }
function Fail($Message) { Write-Host "[MEDfl] ERROR: $Message" -ForegroundColor Red; exit 1 }

$principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
  Fail "open PowerShell as administrator, then run this script again"
}
[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
$Arch = if ($env:PROCESSOR_ARCHITECTURE -eq "ARM64") { "arm64" } else { "amd64" }

# ---------- 1. Tailscale ----------
$Ts = Join-Path $env:ProgramFiles "Tailscale\tailscale.exe"
if (-not (Test-Path $Ts)) {
  Info "Installing Tailscale..."
  $msi = Join-Path $env:TEMP "tailscale-setup.msi"
  Invoke-WebRequest -UseBasicParsing "https://pkgs.tailscale.com/stable/tailscale-setup-latest-$Arch.msi" -OutFile $msi
  Start-Process msiexec.exe -ArgumentList "/i `"$msi`" /qn" -Wait
  Start-Sleep -Seconds 5
  if (-not (Test-Path $Ts)) { Fail "the Tailscale installation failed: install it from https://tailscale.com/download/windows, then run this script again" }
}
& $Ts status *> $null
if ($LASTEXITCODE -eq 0) {
  Info "Tailscale is already connected."
} elseif ($AuthKey) {
  Info "Joining the study network..."
  & $Ts up --authkey $AuthKey --hostname $SiteId --unattended
  if ($LASTEXITCODE -ne 0) { Fail "tailscale up failed: the join key may be used or expired, ask the coordinator for a new script" }
} else {
  Info "Sign in to the study network with the link below (accept the coordinator's invitation first)."
  & $Ts up --hostname $SiteId --unattended
}

# ---------- 2. Python 3.10 to 3.12 ----------
function Find-Python {
  if (-not (Get-Command py -ErrorAction SilentlyContinue)) { return $null }
  foreach ($version in "3.12", "3.11", "3.10") {
    $exe = & py "-$version" -c "import sys; print(sys.executable)" 2>$null
    if ($LASTEXITCODE -eq 0 -and $exe) { return @{ Exe = "$exe".Trim(); Version = $version } }
  }
  return $null
}
$Python = Find-Python
if (-not $Python) {
  Info "Installing Python 3.12..."
  $installer = Join-Path $env:TEMP "python-3.12-installer.exe"
  $suffix = if ($Arch -eq "arm64") { "arm64" } else { "amd64" }
  Invoke-WebRequest -UseBasicParsing "https://www.python.org/ftp/python/3.12.10/python-3.12.10-$suffix.exe" -OutFile $installer
  Start-Process $installer -ArgumentList "/quiet InstallAllUsers=1 PrependPath=1 Include_launcher=1" -Wait
  $env:Path = [Environment]::GetEnvironmentVariable("Path", "Machine") + ";" + [Environment]::GetEnvironmentVariable("Path", "User")
  $Python = Find-Python
}
if (-not $Python) { Fail "Python 3.10, 3.11 or 3.12 is required: install it from https://www.python.org/downloads/windows/ (tick the py launcher), then run this script again" }
Info "Using $($Python.Exe)"

# ---------- 3. Agent ----------
New-Item -ItemType Directory -Force -Path $Base, "$Base\data", "$Base\logs" | Out-Null
Info "Downloading the MEDfl agent from the coordinator ($Coordinator)..."
$url = "http://${Coordinator}:$Port/medfl/agent/medfl_agent.py"
for ($i = 1; $i -le 30; $i++) {
  try {
    Invoke-WebRequest -UseBasicParsing $url -OutFile "$Base\medfl_agent.py"
    break
  } catch {
    if ($i -eq 30) { Fail "cannot reach the coordinator at ${Coordinator}:${Port}: check that MEDomics is open on the coordinator and that this PC is in the study network" }
    Start-Sleep -Seconds 2
  }
}
$config = [ordered]@{
  ctrl_url       = "ws://${Coordinator}:$Port/medfl/rw/ws/agent"
  agent_id       = $SiteId
  base_dir       = $Base
  token          = $Token
  python_version = $Python.Version
}
[IO.File]::WriteAllText("$Base\medfl_agent.json", ($config | ConvertTo-Json), (New-Object Text.UTF8Encoding $false))

# ---------- 4. Start at login ----------
$TaskName = "MEDfl agent $SiteId"
$action = New-ScheduledTaskAction -Execute $Python.Exe -Argument "`"$Base\medfl_agent.py`"" -WorkingDirectory $Base
$trigger = New-ScheduledTaskTrigger -AtLogOn -User "$env:USERDOMAIN\$env:USERNAME"
$settings = New-ScheduledTaskSettingsSet -ExecutionTimeLimit ([TimeSpan]::Zero) -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1) -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable
Register-ScheduledTask -TaskName $TaskName -Action $action -Trigger $trigger -Settings $settings -Force | Out-Null
Start-ScheduledTask -TaskName $TaskName
Info "The agent runs as the scheduled task '$TaskName': keep its window open, it restarts at every login."

Info "Done."
Info "Put the site's files in $Base\data: dataset.csv (training) and, for the holdout test, holdout.csv."
Info "The first start installs MEDfl (10 to 20 minutes). Follow it in $Base\logs\agent.log"
